// CreateTableWithDBType creates the FA_Ledger_Entry table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *FALedgerEntry) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, FALedgerEntryTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetFALedgerEntryPostgresTableSchema()
	} else {
		schema = GetFALedgerEntryTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create FA_Ledger_Entry table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *FALedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, FALedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, fa_posting_date)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$fa_book_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, fa_posting_category, fa_posting_type, fa_posting_date, part_of_book_value, reclassification_entry)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$fa_book_type", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_type: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, part_of_book_value, fa_posting_date)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$fa_book_value", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_value: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, part_of_depreciable_basis, fa_posting_date)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$fa_book_basis", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_basis: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (fa_no, depreciation_book_code, fa_posting_category, fa_posting_type, posting_date)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$fa_book_type_posting_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index fa_book_type_posting_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (canceled_from_fa_no, depreciation_book_code, fa_posting_date)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$canceled_from", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index canceled_from: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (g_l_entry_no)`,
		fmt.Sprintf("%s$FA_Ledger_Entry$g_l_entry", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index g_l_entry: %w", err)
	}
	var keys []sift.Key
	for _, spec := range fALedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, FALedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, FALedgerEntryTableName, keys)
}

// fALedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func fALedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "fa_book_date",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "fa_posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "fa_book_type",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "fa_posting_category", Kind: sift.KindInt}, {Name: "fa_posting_type", Kind: sift.KindInt}, {Name: "fa_posting_date", Kind: sift.KindDate}, {Name: "part_of_book_value", Kind: sift.KindBool}, {Name: "reclassification_entry", Kind: sift.KindBool}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "fa_book_value",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "part_of_book_value", Kind: sift.KindBool}, {Name: "fa_posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "fa_book_basis",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "part_of_depreciable_basis", Kind: sift.KindBool}, {Name: "fa_posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
		{
			Name:   "fa_book_type_posting_date",
			Fields: []sift.Column{{Name: "fa_no", Kind: sift.KindText}, {Name: "depreciation_book_code", Kind: sift.KindText}, {Name: "fa_posting_category", Kind: sift.KindInt}, {Name: "fa_posting_type", Kind: sift.KindInt}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "amount", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *FALedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, FALedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range fALedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, FALedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: FALedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, FALedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

